using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionPluginContracts;
using W=System.Windows.Controls;
using Brushes=System.Windows.Media.Brushes;
using HorizontalAlignment=System.Windows.HorizontalAlignment;
namespace VisionPlugins.CameraMapping;
public static class CameraMappingPointPairControls {
 public static void Register(ToolConfigurationControlRegistry registry,IToolConfigurationSubscriptionService? subscriptions,Func<string,string> text,Action<ToolConfigurationControlContext> opened,Func<string,bool,bool> visible,Action<string,bool> notify){
  registry.Register("PointPair",c=>{
   var selectors=new List<(string Tag,ToolConfigurationSubscriptionSelector Selector)>();bool? previousMode=null;var root=new W.Grid{Margin=new Thickness(0,0,10,0)};root.RowDefinitions.Add(new(){Height=new GridLength(32)});root.RowDefinitions.Add(new(){Height=GridLength.Auto});var title=new W.TextBlock{Margin=new Thickness(18,0,0,0),FontSize=14,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center};root.Children.Add(title);
   var delete=Icon("delete",()=>{opened(c);foreach(var e in new[]{"ObjectPoint","TargetPoint","ObjectPointX","TargetPointX","ObjectPointY","TargetPointY"}.Select(tag=>c.Element.Children.Single(e=>e.Tag==tag))){var n=c.State.GetNode(e)!;var query=ConfigurationSubscriptionValidation.FromElement(e);if(query is null||subscriptions is null){notify("订阅服务不可用，不能删除点对。",true);return;}var result=subscriptions.Bind(query.Destination,null);if(result.Status!=ConfigurationSubscriptionStatus.Available||!c.State.ApplySubscription(n,result)){notify(result.Diagnostic??"清除点订阅失败。",true);return;}}visible(c.Node.Name!,false);});delete.Name="CameraMappingDelete"+c.Node.Name;delete.HorizontalAlignment=HorizontalAlignment.Right;root.Children.Add(delete);
   var rows=new W.StackPanel();W.Grid.SetRow(rows,1);root.Children.Add(rows);var point=Row("Point","TargetPoint","ObjectPoint");var x=Row("PointX","TargetPointX","ObjectPointX");var y=Row("pointy","TargetPointY","ObjectPointY");rows.Children.Add(point);rows.Children.Add(x);rows.Children.Add(y);
   W.Grid Row(string caption,string left,string right){var row=new W.Grid();row.ColumnDefinitions.Add(new(){Width=new GridLength(50)});row.ColumnDefinitions.Add(new(){Width=new GridLength(140)});row.ColumnDefinitions.Add(new(){Width=new GridLength(18)});row.ColumnDefinitions.Add(new(){Width=new GridLength(140)});row.Children.Add(new W.TextBlock{Text=text(caption),FontSize=14,Foreground=Brushes.Gray,VerticalAlignment=VerticalAlignment.Center,FontWeight=FontWeights.Normal});var separator=new System.Windows.Shapes.Rectangle{Height=1,Fill=Brushes.Gray,Margin=new Thickness(3,0,3,0)};W.Grid.SetColumn(separator,2);row.Children.Add(separator);Add(left,1);Add(right,3);return row;
    void Add(string name,int column){var e=c.Element.Children.Single(x=>x.Tag==name);var child=c.CreateChild(e);var selector=ToolConfigurationSubscriptionControls.CreateInline(child,subscriptions,false,text);selectors.Add((name,selector));selector.Margin=new Thickness(0,5,0,5);selector.Width=140;W.Grid.SetColumn(selector,column);row.Children.Add(selector);}
   }
   c.OnRefresh(()=>{bool byPoint=!bool.TryParse(c.Node.Get("IsPointMode"),out var mode)||mode;if(previousMode!=byPoint){previousMode=byPoint;foreach(var item in selectors.Where(item=>byPoint?item.Tag is "ObjectPoint" or "TargetPoint":item.Tag is not ("ObjectPoint" or "TargetPoint")))item.Selector.Read();}point.Visibility=byPoint?Visibility.Visible:Visibility.Collapsed;x.Visibility=y.Visibility=byPoint?Visibility.Collapsed:Visibility.Visible;var active=c.State.GetChildren(c.Element.Parent!).Select(c.State.GetNode).Where(n=>n?.Element.Tag=="PointPair"&&n.CustomVisible).ToArray();int index=Array.IndexOf(active,c.Node)+1;title.Text=text("对位示教点")+index+"—"+text("Unfixtured Point")+index;delete.Visibility=c.Node.Get("Fixed")=="True"||active.Length<=1?Visibility.Collapsed:Visibility.Visible;});return new W.Border{Child=root};
  });
  registry.Register("AddButton_PointPair",c=>{var button=Icon("add",()=>{opened(c);var pair=c.State.Nodes.FirstOrDefault(n=>n.Element.Tag=="PointPair"&&!n.CustomVisible);if(pair is null){notify(text("最多添加")+":8",true);return;}if(visible(pair.Name!,true))c.State.MoveBefore(pair.Element,c.Element);});button.Name="CameraMappingAddPair";button.HorizontalAlignment=HorizontalAlignment.Left;button.Margin=new Thickness(34,8,40,9);button.Height=20;ToolConfigurationView.SetUseItemMargin(button,false);return button;});
 }
 static W.Button Icon(string name,Action action){var image=new W.Image{Source=new BitmapImage(new Uri("pack://application:,,,/VisionPlugins.CameraMapping;component/Resources/"+name+"_normal.png")),Stretch=Stretch.None};var button=new W.Button{Content=image,Background=Brushes.Transparent,BorderThickness=new Thickness(0)};button.MouseEnter+=(_,_)=>image.Source=new BitmapImage(new Uri("pack://application:,,,/VisionPlugins.CameraMapping;component/Resources/"+name+"_click.png"));button.MouseLeave+=(_,_)=>image.Source=new BitmapImage(new Uri("pack://application:,,,/VisionPlugins.CameraMapping;component/Resources/"+name+"_normal.png"));button.Click+=(_,_)=>action();return button;}
 public static FrameworkElement Command(ToolConfigurationControlContext c,string caption,Action action){var button=new W.Button{Content=caption,FontSize=14};button.Click+=(_,_)=>action();return button;}
}
